function setText(k, t) { written[k] = t; FIELDS[k].setValue(t); }
function dirty(k) { return String(FIELDS[k].getValue()) !== written[k]; }
function anyDirty() { for (var k in FIELDS) { if (dirty(k)) { return true; } } return false; }

